// collapse the raw samples of one window into a single stored rollup point
function rollup(samples) {
  // samples: [{ ts, value }, ...] for one time window of one series
  let sum = 0;
  for (const s of samples) sum += s.value;
  const avg = sum / samples.length;
  return { value: avg };   // store the window's average
}
